// Single routing point. In RedBot an inline button press arrives here as a
// plain text message whose content is the button's callback_data.

const cfg = flow.get('cfg');
const i18n = flow.get('i18n');
const chat = msg.chat();
const type = msg.payload.type;
const text = (msg.payload.content || '').toString().trim();

// Resolve the language once; every branch then just reads msg.lang.
const raw = msg.originalMessage && msg.originalMessage.from
    ? (msg.originalMessage.from.language_code || '') : '';
const short = raw.slice(0, 2);
msg.lang = i18n[short] ? short : cfg.defaultLang;

// Outputs: 0=menu 1=about 2=calc 3=rates 4=fallback
const OUT = { menu: 0, about: 1, calc: 2, rates: 3, fallback: 4 };
const route = (i) => { const o = [null, null, null, null, null]; o[i] = msg; return o; };

// Non-text input (photo, sticker, location) must not go unanswered either.
if (type !== 'message') {
    msg.logStep = 'router:non_text';
    return route(OUT.fallback);
}

// /start and /menu reset the dialog from anywhere.
if (text === cfg.command.start || text === cfg.command.menu || text === cfg.action.main) {
    await Promise.resolve(chat.set('mode', 'idle'));
    return route(OUT.menu);
}

if (text === cfg.action.calc) {
    await Promise.resolve(chat.set('mode', 'calc'));
    return route(OUT.calc);
}
if (text === cfg.action.rates) {
    await Promise.resolve(chat.set('mode', 'idle'));
    return route(OUT.rates);
}
if (text === cfg.action.about) {
    await Promise.resolve(chat.set('mode', 'idle'));
    return route(OUT.about);
}

// Free text: the chat mode decides where it goes.
const mode = await Promise.resolve(chat.get('mode'));
if (mode === 'calc') {
    return route(OUT.calc);
}

return route(OUT.fallback);

const cfg = flow.get('cfg');
const i18n = flow.get('i18n');
const t = i18n[msg.lang] || i18n[cfg.defaultLang];

// Kept in node code, not in config: flow context holds data only.
const fmt = (s, v) => s.replace(/\{(\w+)\}/g, (_, k) => (v && v[k] != null ? v[k] : ''));

const chatId = msg.payload.chatId;   // read before payload is overwritten

msg.logStep = 'menu:shown';
msg.logDetail = 'main menu lang=' + msg.lang;

msg.payload = {
    type: 'inline-buttons',
    chatId,
    content: t.menu_title,
    buttons: [
        { type: 'postback', label: t.btn_calc,  value: cfg.action.calc },
        { type: 'newline' },
        { type: 'postback', label: t.btn_rates, value: cfg.action.rates },
        { type: 'newline' },
        { type: 'postback', label: t.btn_about, value: cfg.action.about }
    ]
};
return msg;

const cfg = flow.get('cfg');
const i18n = flow.get('i18n');
const t = i18n[msg.lang] || i18n[cfg.defaultLang];

// Kept in node code, not in config: flow context holds data only.
const fmt = (s, v) => s.replace(/\{(\w+)\}/g, (_, k) => (v && v[k] != null ? v[k] : ''));

const chatId = msg.payload.chatId;

msg.logStep = 'about:shown';
msg.logDetail = 'about screen';

msg.payload = {
    type: 'inline-buttons',
    chatId,
    content: t.about,
    buttons: [{ type: 'postback', label: t.btn_back, value: cfg.action.main }]
};
return msg;

const cfg = flow.get('cfg');
const i18n = flow.get('i18n');
const t = i18n[msg.lang] || i18n[cfg.defaultLang];

// Kept in node code, not in config: flow context holds data only.
const fmt = (s, v) => s.replace(/\{(\w+)\}/g, (_, k) => (v && v[k] != null ? v[k] : ''));

// Calculator. Input format is a single line, "12 + 7" - a deliberate choice:
// step-by-step prompting needs intermediate state and mid-dialog exit handling,
// while the validation requirements are covered either way.

const chatId = msg.payload.chatId;
const input = (msg.payload.content || '').toString();
const MAX_LEN = cfg.calc.maxLen;

const BACK = [{ type: 'postback', label: t.btn_back, value: cfg.action.main }];

const reply = (text, step, detail) => {
    msg.logStep = 'calc:' + step;
    msg.logDetail = detail !== undefined ? detail : input.trim().slice(0, 80);
    msg.payload = { type: 'inline-buttons', chatId, content: text, buttons: BACK };
    return msg;
};

// Entered the branch via the button - show the input format.
if (input.trim() === cfg.action.calc) {
    return reply(t.calc_title + '\n' + t.calc_hint, 'branch_entered', 'entered');
}

const trimmed = input.trim();
if (trimmed === '') {
    return reply(t.calc_empty + ' ' + t.calc_hint, 'empty_input', '<empty>');
}

// Length is checked before parsing: a huge string in a backtracking regex is a ReDoS risk.
if (trimmed.length > MAX_LEN) {
    return reply(fmt(t.calc_too_long, { len: trimmed.length, max: MAX_LEN }) + '\n' + t.calc_hint,
                 'too_long', 'len=' + trimmed.length);
}

// Human symbols to machine ones.
const norm = trimmed
    .replace(/×/g, '*')
    .replace(/÷/g, '/')
    .replace(/[−–—]/g, '-')
    .replace(',', '.');

// Lazy quantifier so that a leading minus stays with the left operand: "-5+3".
const m = norm.match(/^(.+?)\s*([+\-*/])\s*(.+)$/);
if (m === null) {
    return reply(fmt(t.calc_no_operator, { expr: trimmed }) + '\n' + t.calc_hint, 'no_operator');
}

const left = m[1].trim();
const op = m[2];
const right = m[3].trim();

// An operand must be a bare number. Checking the shape, not just Number(),
// lets us tell "not a number" apart from "more than one operation".
const NUMBER = /^-?\d+(?:\.\d+)?$/;
const OPERATOR = /[+\-*/]/;

const badOperand = !NUMBER.test(left) ? left : (!NUMBER.test(right) ? right : null);

if (badOperand !== null) {
    // "1+1/2" used to report "1/2 is not a number", which is a lie.
    if (OPERATOR.test(badOperand.slice(1))) {
        return reply(t.calc_one_op + '\n' + t.calc_hint, 'too_many_operations', 'expr=' + trimmed);
    }
    return reply(fmt(t.calc_not_number, { bad: badOperand }) + '\n' + t.calc_hint,
                 'invalid_number', 'bad=' + badOperand);
}

// Number('') is 0, not NaN - the shape check above already rejects an empty operand.
const a = Number(left);
const b = Number(right);

// Number.isFinite does no coercion and also rejects Infinity.
if (!Number.isFinite(a) || !Number.isFinite(b)) {
    const bad = !Number.isFinite(a) ? left : right;
    return reply(fmt(t.calc_not_number, { bad }) + '\n' + t.calc_hint, 'invalid_number', 'bad=' + bad);
}

if (op === '/' && b === 0) {
    return reply(t.calc_div_zero + '\n' + t.calc_hint, 'division_by_zero');
}

let result;
switch (op) {
    case '+': result = a + b; break;
    case '-': result = a - b; break;
    case '*': result = a * b; break;
    case '/': result = a / b; break;
}

if (!Number.isFinite(result)) {
    return reply(t.calc_overflow + '\n' + t.calc_hint, 'overflow');
}

// Trim float noise: 0.1 + 0.2 = 0.30000000000000004
const p = cfg.calc.precision;
const pretty = Math.round(result * p) / p;

return reply(fmt(t.calc_result, { a, op, b, r: pretty }), 'success', a + op + b + '=' + pretty);

// Exchange rates branch, request side.
// Outputs: 0 = go to the HTTP node, 1 = straight to the error handler.
// The second output exists because on an invalid URL the http request node
// only emits a warn and drops the message - a warn does not trigger Catch,
// so the user was left with no reply at all.

const cfg = flow.get('cfg');
const url = cfg.nbu.url;
const timeout = cfg.nbu.timeoutMs;

// The HTTP node overwrites msg.payload with the response, so chatId has to
// leave the payload now or it is lost.
msg.chatIdSaved = msg.payload.chatId;

if (!/^https?:\/\//.test(url)) {
    msg.error = { message: 'invalid nbu.url: ' + String(url).slice(0, 40) };
    return [null, msg];              // no request was sent, so nothing is logged as sent
}

msg.url = url;                       // the node's URL field is empty, so it takes msg.url
msg.requestTimeout = timeout;        // otherwise the global 120s limit applies
// msg.method is not set: the method is configured on the node and msg cannot override it

msg.logStep = 'nbu:request_sent';
msg.logDetail = url + ' timeout=' + timeout + 'ms';

return [msg, null];

const cfg = flow.get('cfg');
const i18n = flow.get('i18n');
const t = i18n[msg.lang] || i18n[cfg.defaultLang];

// Kept in node code, not in config: flow context holds data only.
const fmt = (s, v) => s.replace(/\{(\w+)\}/g, (_, k) => (v && v[k] != null ? v[k] : ''));

// Unrecognised input: explain, then show the menu again.
const chatId = msg.payload.chatId;
const got = (msg.payload.content || '').toString().slice(0, 40);

msg.logStep = msg.logStep || 'fallback:unknown_input';
msg.logDetail = got;

msg.payload = {
    type: 'inline-buttons',
    chatId,
    content: fmt(t.fallback, { got }),
    buttons: [
        { type: 'postback', label: t.btn_calc,  value: cfg.action.calc },
        { type: 'newline' },
        { type: 'postback', label: t.btn_rates, value: cfg.action.rates },
        { type: 'newline' },
        { type: 'postback', label: t.btn_about, value: cfg.action.about }
    ]
};
return msg;

// Single logging point, reached from every branch through link call.
// Output 0 forwards the untouched msg, output 1 carries the log line to the
// file node - the file node writes msg.payload, which we must not overwrite.

const p = msg.payload || {};

const entry = {
    ts: new Date().toISOString(),
    chatId: p.chatId != null ? p.chatId : (msg.chatIdSaved != null ? msg.chatIdSaved : null),
    step: msg.logStep || 'msg:received',
    detail: (msg.intentMatched ? '[' + msg.intentMatched + '] ' : '') + (
        msg.logDetail != null
            ? msg.logDetail
            : (typeof p.content === 'string' ? p.content.slice(0, 80) : p.type))
};

const line = JSON.stringify(entry);

node.log(line);            // container stdout -> docker logs

delete msg.logStep;        // so the next call does not repeat this one
delete msg.logDetail;
delete msg.intentMatched;

return [msg, { payload: line }];

const cfg = flow.get('cfg');
const i18n = flow.get('i18n');
const t = i18n[msg.lang] || i18n[cfg.defaultLang];

// Kept in node code, not in config: flow context holds data only.
const fmt = (s, v) => s.replace(/\{(\w+)\}/g, (_, k) => (v && v[k] != null ? v[k] : ''));

// Exchange rates branch, response side. Three ways in:
//   1) success        - statusCode 200, payload is an array
//   2) network error  - the HTTP node forwards msg with the code in statusCode
//   3) exception      - the Catch node, or our own URL guard in the rates node

const chatId = msg.chatIdSaved;
const BACK = [{ type: 'postback', label: t.btn_back, value: cfg.action.main }];

const reply = (text, step, detail) => {
    msg.logStep = 'nbu:' + step;
    msg.logDetail = detail;
    msg.payload = { type: 'inline-buttons', chatId, content: text, buttons: BACK };
    return msg;
};

if (msg.error != null) {
    return reply(t.rates_error, 'error', 'exception:' + (msg.error.message || 'unknown'));
}

if (msg.statusCode !== 200) {
    return reply(t.rates_error, 'error', 'status=' + msg.statusCode);
}

// 200 but not what we expect: HTML instead of JSON, a stub, an empty body.
const data = msg.payload;
if (!Array.isArray(data)) {
    return reply(t.rates_error, 'error', 'bad_body:' + typeof data);
}

const rows = cfg.nbu.currencies.map((cc) => data.find((row) => row.cc === cc));
if (rows.some((row) => row == null)) {
    return reply(t.rates_error, 'error', 'missing_currency');
}

const num = (row) => Number(row.rate).toFixed(4);
const [usd, eur] = rows;

return reply(
    fmt(t.rates_ok, { date: usd.exchangedate, usd: num(usd), eur: num(eur) }),
    'success',
    'USD=' + num(usd) + ' EUR=' + num(eur)
);

