// Single source of truth for constants and user-facing strings.
// Runs on the On Start tab, before the first message reaches the flow.
// Data only, no functions: flow context may be moved to a persistent
// store, and a function would not survive serialisation.

flow.set('cfg', {
    defaultLang: 'uk',

    calc: {
        maxLen: 50,          // max expression length
        precision: 1e10      // result rounding
    },

    nbu: {
        url: 'https://bank.gov.ua/NBUStatService/v1/statdirectory/exchange?json',
        timeoutMs: 5000,     // set to 1 to reproduce an external service failure
        currencies: ['USD', 'EUR']
    },

    // button callback_data values; Telegram caps these at 64 bytes
    action: {
        main:  'menu:main',
        calc:  'menu:calc',
        rates: 'menu:rates',
        about: 'menu:about'
    },

    command: {
        start: '/start',
        menu:  '/menu'
    },

    // Free-text recognition. Stored as strings, not RegExp objects, so the
    // config stays serialisable; the intent node compiles them with new RegExp.
    intent: {
        rates: 'курс|валют|долар|євро|гривн|dollar|euro|rate|exchange|usd|eur',
        calc:  'калькул|порахуй|порахува|обчисл|полічи|calculator|calculate',
        menu:  'меню|назад|початок|menu|back|start',
        ops: [
            { re: 'плюс|додати|прибав|plus|add',                op: '+' },
            { re: 'мінус|відняти|minus|subtract|less',          op: '-' },
            { re: 'помнож|множ|разів|рази|times|multipl',       op: '*' },
            { re: 'поділ|розділ|ділен|ділит|divid|over',        op: '/' }
        ]
    }
});

// {name} placeholders are substituted by the fmt() helper in the nodes.
flow.set('i18n', {
    uk: {
        btn_calc:  '🧮 Калькулятор',
        btn_rates: '💱 Курс валют',
        btn_about: 'ℹ️ Про бота',
        btn_back:  '⬅️ Назад',

        menu_title: 'Головне меню. Обери пункт:',

        about: 'ℹ️ Тестовий бот на RedBot (Node-RED).\nУміє: калькулятор і курс валют НБУ.\n/menu — головне меню в будь-який момент.',

        calc_title:      '🧮 Калькулятор.',
        calc_hint:       'Надішли вираз одним рядком, напр.: 12 + 7\nДії: + − × ÷ (можна * і /)',
        calc_empty:      'Порожнє повідомлення.',
        calc_too_long:   'Задовгий вираз ({len} символів, максимум {max}).',
        calc_no_operator:'Не бачу дії у виразі «{expr}».',
        calc_not_number: '«{bad}» — не число.',
        calc_one_op:     'Рахую лише одну дію за раз.',
        calc_div_zero:   'На нуль ділити не можна.',
        calc_overflow:   'Результат виходить за межі чисел, які я вмію рахувати.',
        calc_result:     '🧮 {a} {op} {b} = {r}\n\nЩе вираз? Надішли наступний.',

        rates_ok:    '💱 Курс НБУ на {date}\n\n🇺🇸 USD — {usd} ₴\n🇪🇺 EUR — {eur} ₴',
        rates_error: 'Не вдалося отримати курс, спробуйте пізніше.',

        fallback: 'Не зрозумів «{got}».\nОбери пункт нижче або надішли /menu.'
    },

    en: {
        btn_calc:  '🧮 Calculator',
        btn_rates: '💱 Exchange rates',
        btn_about: 'ℹ️ About',
        btn_back:  '⬅️ Back',

        menu_title: 'Main menu. Pick an option:',

        about: 'ℹ️ Test bot built on RedBot (Node-RED).\nDoes: a calculator and NBU exchange rates.\n/menu returns here at any time.',

        calc_title:      '🧮 Calculator.',
        calc_hint:       'Send an expression on one line, e.g.: 12 + 7\nOperators: + − × ÷ (also * and /)',
        calc_empty:      'Empty message.',
        calc_too_long:   'Expression too long ({len} characters, limit {max}).',
        calc_no_operator:'No operator found in "{expr}".',
        calc_not_number: '"{bad}" is not a number.',
        calc_one_op:     'I can only compute one operation at a time.',
        calc_div_zero:   'Division by zero is not allowed.',
        calc_overflow:   'The result is outside the range I can compute.',
        calc_result:     '🧮 {a} {op} {b} = {r}\n\nAnother one? Just send it.',

        rates_ok:    '💱 NBU rates for {date}\n\n🇺🇸 USD — {usd} UAH\n🇪🇺 EUR — {eur} UAH',
        rates_error: 'Could not fetch the rates, please try again later.',

        fallback: 'I did not understand "{got}".\nPick an option below or send /menu.'
    }
});

node.log(JSON.stringify({
    ts: new Date().toISOString(), chatId: null,
    step: 'config:loaded',
    detail: 'langs=' + Object.keys(flow.get('i18n')).join(',')
}));

