// Free-text recognition, sitting on the fallback path only: exact commands and
// button payloads are already handled by the router, so this can never hijack
// an unambiguous input. Recognised text is rewritten into the canonical form
// the existing branches already accept - no branch needs to know about NLU.
//
// Outputs: 0=calc 1=rates 2=fallback 3=menu

const cfg = flow.get('cfg');
const chat = msg.chat();
const text = (msg.payload.content || '').toString();

const route = (i, matched, content) => {
    if (content !== undefined) { msg.payload.content = content; }
    msg.intentMatched = matched;      // shown by the log node, then dropped
    const o = [null, null, null, null];
    o[i] = msg;
    return o;
};

// 1. Arithmetic already written with symbols, possibly wrapped in words:
//    "скільки буде 5+7" -> "5+7"
const direct = text.match(/(-?\d+(?:[.,]\d+)?)\s*([+\-*\/×÷])\s*(-?\d+(?:[.,]\d+)?)/);
if (direct !== null) {
    return route(0, 'calc:symbols', direct[0]);
}

// 2. Arithmetic spelled out in words: "скільки буде 5 плюс 7" -> "5 + 7"
const worded = text.match(/(-?\d+(?:[.,]\d+)?)\s+([^\d\s]+(?:\s+[^\d\s]+)?)\s+(-?\d+(?:[.,]\d+)?)/);
if (worded !== null) {
    for (const entry of cfg.intent.ops) {
        if (new RegExp(entry.re, 'i').test(worded[2])) {
            return route(0, 'calc:words', worded[1] + ' ' + entry.op + ' ' + worded[3]);
        }
    }
}

// 3. Currency question: "який курс долара"
if (new RegExp(cfg.intent.rates, 'i').test(text)) {
    return route(1, 'rates');
}

// 4. Branch named in words: "калькулятор". Set the mode too, so the next bare
//    expression is treated as calculator input, exactly as after a button tap.
if (new RegExp(cfg.intent.calc, 'i').test(text)) {
    await Promise.resolve(chat.set('mode', 'calc'));
    return route(0, 'calc:branch', cfg.action.calc);
}

// 5. "меню", "назад" - back to the top
if (new RegExp(cfg.intent.menu, 'i').test(text)) {
    await Promise.resolve(chat.set('mode', 'idle'));
    return route(3, 'menu');
}

// 6. Nothing recognised - the normal fallback answer
return route(2, 'none');
